// Generated by Cypress Author on 2026-10-22
//
// VER 01–08 (servidor) — Plano_de_Testes_QA_MatchWallet.md §6 (docs-test/areas/ver.md).
// Não há UI de autoria/publicação (Edicao/Revisao/AdicionarAtivo estão desligadas e não existe
// catálogo de ativos na API): o "fluxo autorizado" é a API de admin (`POST /carteiras/:id/versoes`
// e `/versoes/:id/publicar`), e o resultado é conferido também na tela do cliente (catálogo).
// Cada teste usa uma CARTEIRA PRÓPRIA (criada e desativada aqui) e ativos já existentes.
//
// Limites: não há `GET` de uma versão antiga por id nem endpoint de edição de versão — a leitura
// do histórico passa por `/versoes` (resumo), `/movimentacoes?mesReferencia=` e relatórios.
// VER 07 dispara requisições paralelas com `fetch` do navegador (o cookie de sessão vai junto); o
// resultado de uma corrida pode variar entre execuções, então uma falha ocasional é sinal real.
//
// Falham até correção (marcados no título):
//  - peso 0 é aceito num item (colide com a linha de SAIU, que também tem peso 0);
//  - `/movimentacoes` recalcula contra a versão anterior no momento da leitura: publicar uma
//    competência ANTIGA depois muda as movimentações de uma competência já publicada.

import { competenciaRelativa } from '../../support/commands/fluxos'

interface Resposta {
  status: number
  body: Versao | null
}

interface Item {
  ativoId: string
  pesoPercentual: number
}

interface Versao {
  id: string
  mesReferencia: string
  publicada: boolean
  publicadaEm: string | null
  itens?: Array<{ ativoId: string; pesoPercentual: number; statusMovimentacao: string }>
}

interface Resumo {
  id: string
  mesReferencia: string
  publicada: boolean
  publicadaEm: string | null
  totalItens: number
}

interface Detalhe {
  versaoAtual: { mesReferencia: string; publicada: boolean; itens: Item[] } | null
}

interface Movimentacoes {
  movimentacoes: {
    entradas: Array<{ ticker: string; pesoAtual: number }>
    saidas: Array<{ ticker: string; pesoAnterior: number }>
    alteracoes: Array<{ ticker: string; pesoAnterior: number; pesoAtual: number; tipo: string }>
    mantidos: Array<{ ticker: string; peso: number }>
  }
}

const RECUSADO = [400, 422]
const carteirasCriadas: string[] = []
const M = competenciaRelativa()
const MENOS_1 = competenciaRelativa(-1)

function comoAdmin() {
  cy.clearCookies()
  cy.loginReal('admin')
}

function novaCarteira() {
  return cy.criarCarteiraDeTeste().then((id) => {
    carteirasCriadas.push(id)
    return id
  })
}

function itens(ativos: string[], pesos: number[]): Item[] {
  return ativos.map((ativoId, i) => ({ ativoId, pesoPercentual: pesos[i] }))
}

function criarVersao(carteiraId: string, mesReferencia: unknown, lista: unknown) {
  return cy.apiRequest<Versao>({
    method: 'POST',
    url: `/carteiras/${carteiraId}/versoes`,
    body: { mesReferencia, itens: lista },
    failOnStatusCode: false,
  })
}

function publicar(carteiraId: string, versaoId: string) {
  return cy.apiRequest<Versao>({
    method: 'POST',
    url: `/carteiras/${carteiraId}/versoes/${versaoId}/publicar`,
    failOnStatusCode: false,
  })
}

/** Cria e publica; falha o teste se qualquer passo não for 2xx. */
function criarEPublicar(carteiraId: string, mes: string, lista: Item[]) {
  return criarVersao(carteiraId, mes, lista).then(({ status, body }) => {
    expect(status, `criar ${mes}`).to.eq(201)
    return publicar(carteiraId, body.id).then(({ status: publicou, body: publicada }) => {
      expect(publicou, `publicar ${mes}`).to.be.within(200, 201)
      return publicada
    })
  })
}

function versoes(carteiraId: string) {
  return cy
    .apiRequest<{ items: Resumo[] }>({
      method: 'GET',
      url: `/carteiras/${carteiraId}/versoes?pageSize=100`,
    })
    .then(({ body }) => body.items)
}

function detalhe(carteiraId: string) {
  return cy.apiRequest<Detalhe>({ method: 'GET', url: `/carteiras/${carteiraId}` }).its('body')
}

function movimentacoes(carteiraId: string, mes: string) {
  return cy
    .apiRequest<Movimentacoes>({
      method: 'GET',
      url: `/carteiras/${carteiraId}/movimentacoes?mesReferencia=${mes}`,
    })
    .its('body')
}

function baixar(id: string) {
  return cy.apiRequest<string>({
    method: 'GET',
    url: `/relatorios/${id}/download`,
    encoding: 'binary',
  })
}

/** Dispara as requisições ao mesmo tempo, com o cookie de sessão, e devolve status e corpo de cada. */
function emParalelo(
  pedidos: Array<{ method: string; url: string; body?: unknown }>,
): Cypress.Chainable<Resposta[]> {
  const api = String(Cypress.expose('apiUrl'))
  const todas: Promise<Resposta[]> = Promise.all(
    pedidos.map(({ method, url, body }) =>
      fetch(`${api}${url}`, {
        method,
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: body === undefined ? undefined : JSON.stringify(body),
      }).then(async (resposta) => ({
        status: resposta.status,
        body: (await resposta.json().catch(() => null)) as Versao | null,
      })),
    ),
  )
  return cy.wrap(todas) as unknown as Cypress.Chainable<Resposta[]>
}

describe('Plano QA · Composição e versões no servidor', () => {
  after(() => {
    comoAdmin()
    for (const id of carteirasCriadas) cy.desativarCarteira(id)
  })

  it('VER 01 · rascunho para M → persistido por carteira e competência, invisível ao investidor até publicar (API e catálogo)', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(2).then(([a, b]) => {
      novaCarteira().then((carteiraId) => {
        criarVersao(carteiraId, M, itens([a, b], [60, 40])).then(({ status, body }) => {
          expect(status).to.eq(201)
          expect(body.mesReferencia).to.eq(M)
          expect(body.publicada).to.eq(false)
          expect(body.itens).to.have.length(2)
        })

        // Admin enxerga o rascunho, ainda sem data de publicação.
        versoes(carteiraId).should((lista) => {
          expect(lista).to.have.length(1)
          expect(lista[0]).to.include({ mesReferencia: M, publicada: false, totalItens: 2 })
          expect(lista[0].publicadaEm).to.eq(null)
        })

        // Investidor: nada de composição, nem lista de versões, nem movimentações.
        cy.criarUsuarioDescartavel().then((conta) => {
          cy.clearCookies()
          cy.loginComo(conta)
          detalhe(carteiraId).its('versaoAtual').should('eq', null)
          cy.apiRequest({
            method: 'GET',
            url: `/carteiras/${carteiraId}/versoes`,
            failOnStatusCode: false,
          })
            .its('status')
            .should('be.oneOf', [401, 403])
          cy.apiRequest({
            method: 'GET',
            url: `/carteiras/${carteiraId}/movimentacoes?mesReferencia=${M}`,
            failOnStatusCode: false,
          }).then(({ status, body }) => {
            expect(status).to.be.within(400, 499)
            expect(JSON.stringify(body)).not.to.contain('entradas')
          })

          cy.visit('/carteiras')
          cy.contains('[data-slot="wallet-card"]', 'E2E Relatório')
            .should('contain.text', 'Sem versão publicada ainda.')
            .and('contain.text', '0 ativos')
        })
      })
    })
  })

  it('VER 02 · ativo duplicado/inexistente/inválido, peso negativo ou acima do limite e somas ≠ 100 → recusados sem gravar; soma exata e frações que fecham 100 aceitas', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(3).then(([a, b, c]) => {
      novaCarteira().then((carteiraId) => {
        const semelhante = '00000000-0000-4000-8000-000000000000'
        const recusados: Array<[string, unknown, number[]]> = [
          ['ativo duplicado', itens([a, a], [50, 50]), RECUSADO],
          ['ativoId vazio', [{ ativoId: '', pesoPercentual: 100 }], RECUSADO],
          ['ativoId não é UUID', [{ ativoId: 'ITUB4', pesoPercentual: 100 }], RECUSADO],
          ['peso negativo', itens([a, b], [-10, 110]), RECUSADO],
          ['peso acima de 100', itens([a, b], [100.01, -0.01]), RECUSADO],
          ['peso com 3 casas', itens([a, b, c], [33.333, 33.333, 33.334]), RECUSADO],
          ['soma 99,99', itens([a, b, c], [33.33, 33.33, 33.33]), RECUSADO],
          ['soma 100,01', itens([a, b], [50, 50.01]), RECUSADO],
          ['soma 90', itens([a, b], [50, 40]), RECUSADO],
          ['sem itens', [], RECUSADO],
        ].map(([r, i]) => [r as string, i, RECUSADO])
        for (const [rotulo, lista, esperado] of recusados) {
          criarVersao(carteiraId, M, lista)
            .its('status', { log: false })
            .should('be.oneOf', esperado)
          cy.log(`recusado: ${rotulo}`)
        }
        // Ativo inexistente: 404 do servidor.
        criarVersao(carteiraId, M, itens([a, semelhante], [50, 50]))
          .its('status')
          .should('eq', 404)

        // Nada disso foi gravado.
        versoes(carteiraId).should('have.length', 0)

        // Frações que fecham 100 em centésimos aceitam (sem erro de ponto flutuante).
        criarVersao(carteiraId, MENOS_1, itens([a, b, c], [33.33, 33.33, 33.34]))
          .its('status')
          .should('eq', 201)
        criarVersao(carteiraId, M, itens([a, b], [60, 40]))
          .its('status')
          .should('eq', 201)
        versoes(carteiraId).should('have.length', 2)
      })
    })
  })

  // ATENÇÃO — deve FALHAR: `ItemVersaoDto` usa `@Min(0)`, então um item com peso 0 passa.
  it('VER 02 · item com peso zero → recusado (falha até exigir peso maior que zero)', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(2).then(([a, b]) => {
      novaCarteira().then((carteiraId) => {
        criarVersao(carteiraId, M, itens([a, b], [100, 0]))
          .its('status')
          .should('be.oneOf', RECUSADO)
      })
    })
  })

  it('VER 03 · publicação válida → status e data, mesma composição em Versões, detalhe e catálogo', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(2).then(([a, b]) => {
      novaCarteira().then((carteiraId) => {
        criarEPublicar(carteiraId, M, itens([a, b], [70, 30])).then((publicada) => {
          expect(publicada.publicada).to.eq(true)
          expect(publicada.publicadaEm, 'data de publicação').to.be.a('string')
          expect(publicada.mesReferencia).to.eq(M)
        })

        versoes(carteiraId).should((lista) => {
          expect(lista).to.have.length(1)
          expect(lista[0]).to.include({ mesReferencia: M, publicada: true, totalItens: 2 })
          expect(lista[0].publicadaEm).to.be.a('string')
        })

        // Investidor: a composição vigente é a publicada, com os pesos certos.
        cy.criarUsuarioDescartavel().then((conta) => {
          cy.clearCookies()
          cy.loginComo(conta)
          detalhe(carteiraId).then(({ versaoAtual }) => {
            expect(versaoAtual?.mesReferencia).to.eq(M)
            expect(versaoAtual?.publicada).to.eq(true)
            const pesos = Object.fromEntries(
              (versaoAtual?.itens ?? []).map((i) => [i.ativoId, i.pesoPercentual]),
            )
            expect(pesos).to.deep.eq({ [a]: 70, [b]: 30 })
          })

          cy.visit('/carteiras')
          cy.contains('[data-slot="wallet-card"]', 'E2E Relatório')
            .should('contain.text', '2 ativos')
            .contains('button', 'Ver composição')
            .click()
          cy.contains('Composição vigente').should('be.visible')
          cy.contains('Composição · 2 ativos').should('be.visible')
          cy.contains('70,00 %').should('be.visible')
          cy.contains('30,00 %').should('be.visible')
        })
      })
    })
  })

  it('VER 04 · competência vazia/malformada e repetida → formato validado e uma única versão por competência', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(2).then(([a, b]) => {
      novaCarteira().then((carteiraId) => {
        const lista = itens([a, b], [50, 50])
        for (const invalida of ['', '2026-13', '2026-00', '26-10', '2026-1', 'abcd-ef', null]) {
          criarVersao(carteiraId, invalida, lista)
            .its('status', { log: false })
            .should('be.oneOf', RECUSADO)
        }
        versoes(carteiraId).should('have.length', 0)

        criarEPublicar(carteiraId, M, lista)

        // Segunda versão para M, com composição diferente, é recusada (409) — antes e depois de publicar.
        criarVersao(carteiraId, M, itens([a, b], [80, 20]))
          .its('status')
          .should('eq', 409)

        versoes(carteiraId).should((todas) => {
          expect(todas.filter((v) => v.mesReferencia === M)).to.have.length(1)
        })
        // A vigente continua a primeira, sem contradição.
        detalhe(carteiraId)
          .its('versaoAtual.itens')
          .should((vigentes: Item[]) => {
            expect(vigentes.map((i) => i.pesoPercentual).sort()).to.deep.eq([50, 50])
          })
      })
    })
  })

  it('VER 05 · M-1 e M publicadas → vigente é M, histórico lista as duas e o snapshot e o relatório de M-1 não mudam', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(3).then(([a, b, c]) => {
      novaCarteira().then((carteiraId) => {
        criarEPublicar(carteiraId, MENOS_1, itens([a, b], [50, 50]))
        movimentacoes(carteiraId, MENOS_1).as('movAntes')
        cy.gerarRelatorioComEspera({ carteiraId, mesReferencia: MENOS_1 }).then(
          ({ status, body: relatorio }) => {
            expect(status).to.eq(201)
            baixar(relatorio.id).its('body').as('bytesAntes')

            criarEPublicar(carteiraId, M, itens([a, c], [70, 30]))

            // Histórico: duas versões publicadas, cada uma com data.
            versoes(carteiraId).should((lista) => {
              expect(lista.map((v) => v.mesReferencia).sort()).to.deep.eq([MENOS_1, M].sort())
              expect(lista.every((v) => v.publicada && v.publicadaEm)).to.eq(true)
            })

            // Vigente: M, com a composição nova.
            detalhe(carteiraId).then(({ versaoAtual }) => {
              expect(versaoAtual?.mesReferencia).to.eq(M)
              expect(versaoAtual?.itens.map((i) => i.ativoId).sort()).to.deep.eq([a, c].sort())
            })

            // M-1: movimentações e arquivo do relatório seguem como na época.
            cy.get('@movAntes').then((antes) => {
              movimentacoes(carteiraId, MENOS_1).should('deep.equal', antes)
            })
            cy.get('@bytesAntes').then((antes) => {
              baixar(relatorio.id).its('body').should('eq', antes)
            })
          },
        )
      })
    })
  })

  it('VER 06 · versão publicada com relatório emitido → sem edição, republicação ou duplicata, e o relatório segue idêntico', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(2).then(([a, b]) => {
      novaCarteira().then((carteiraId) => {
        criarEPublicar(carteiraId, M, itens([a, b], [60, 40])).then((publicada) => {
          cy.gerarRelatorioComEspera({ carteiraId, mesReferencia: M }).then(
            ({ status, body: relatorio }) => {
              expect(status).to.eq(201)
              baixar(relatorio.id).its('body').as('bytesAntes')

              // Republicar: somente leitura (409).
              publicar(carteiraId, publicada.id).its('status').should('eq', 409)

              // Editar, trocar itens ou remover pela API: nenhuma rota aceita (nunca 2xx).
              const base = `/carteiras/${carteiraId}/versoes/${publicada.id}`
              for (const [method, url, body] of [
                ['PUT', base, { itens: itens([a], [100]) }],
                ['PATCH', base, { itens: itens([a], [100]) }],
                ['DELETE', base, undefined],
                ['DELETE', `${base}/itens/${a}`, undefined],
                ['PUT', `${base}/itens`, { itens: itens([a], [100]) }],
              ] as const) {
                cy.apiRequest({ method, url, body, failOnStatusCode: false })
                  .its('status', { log: false })
                  .should('be.within', 400, 499)
              }
              // Outra versão para a mesma competência (a "revisão" informal): recusada.
              criarVersao(carteiraId, M, itens([a, b], [10, 90]))
                .its('status')
                .should('eq', 409)

              // Nada mudou na composição vigente nem no documento emitido.
              detalhe(carteiraId)
                .its('versaoAtual.itens')
                .should((vigentes: Item[]) => {
                  expect(
                    Object.fromEntries(vigentes.map((i) => [i.ativoId, i.pesoPercentual])),
                  ).to.deep.eq({
                    [a]: 60,
                    [b]: 40,
                  })
                })
              cy.get('@bytesAntes').then((antes) => {
                baixar(relatorio.id).its('body').should('eq', antes)
              })
            },
          )
        })
      })
    })
  })

  it('VER 07 · criação e publicação simultâneas da mesma competência → uma versão vigente coerente, sem duplicata e sem erro 5xx', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(3).then(([a, b, c]) => {
      novaCarteira().then((carteiraId) => {
        criarEPublicar(carteiraId, MENOS_1, itens([a, b], [50, 50]))

        // Duas criações ao mesmo tempo: uma vence (201), a outra é conflito (409).
        const criacao = {
          method: 'POST',
          url: `/carteiras/${carteiraId}/versoes`,
          body: { mesReferencia: M, itens: itens([a, c], [70, 30]) },
        }
        emParalelo([criacao, criacao]).then((respostas) => {
          const status = respostas.map((r) => r.status).sort()
          expect(status, 'criação concorrente').to.deep.eq([201, 409])

          const vencedora = respostas.find((r) => r.status === 201)?.body as Versao

          // Duas publicações ao mesmo tempo da mesma versão: só uma publica.
          const publicacao = {
            method: 'POST',
            url: `/carteiras/${carteiraId}/versoes/${vencedora.id}/publicar`,
          }
          emParalelo([publicacao, publicacao]).then((publicacoes) => {
            const codigos = publicacoes.map((r) => r.status)
            expect(
              codigos.filter((s) => s >= 500),
              'sem erro 5xx',
            ).to.have.length(0)
            expect(
              codigos.filter((s) => s >= 200 && s < 300),
              'uma única publicação',
            ).to.have.length(1)
            expect(codigos.filter((s) => s === 409)).to.have.length(1)
          })
        })

        versoes(carteiraId).should((lista) => {
          expect(lista.filter((v) => v.mesReferencia === M)).to.have.length(1)
          expect(lista.find((v) => v.mesReferencia === M)?.publicada).to.eq(true)
        })
        // Composição coerente e a saída de B registrada uma única vez.
        detalhe(carteiraId)
          .its('versaoAtual.itens')
          .should((vigentes: Item[]) => {
            expect(vigentes.map((i) => i.ativoId).sort()).to.deep.eq([a, c].sort())
          })
        movimentacoes(carteiraId, M).its('movimentacoes.saidas').should('have.length', 1)
      })
    })
  })

  it('VER 08 · M-1 → M com entrada, saída e mudança de peso → movimentações corretas; primeira versão só tem entradas; mês igual só tem mantidos', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(3).then(([a, b, c]) => {
      // Carteira 1: A 50 / B 50 → A 70 / C 30.
      novaCarteira().then((carteiraId) => {
        criarEPublicar(carteiraId, MENOS_1, itens([a, b], [50, 50]))

        // Primeira versão: tudo é entrada, nada saiu, nada foi mantido nem alterado.
        movimentacoes(carteiraId, MENOS_1)
          .its('movimentacoes')
          .should((mov) => {
            expect(mov.entradas).to.have.length(2)
            expect(mov.saidas).to.have.length(0)
            expect(mov.alteracoes).to.have.length(0)
            expect(mov.mantidos).to.have.length(0)
          })

        criarEPublicar(carteiraId, M, itens([a, c], [70, 30]))
        movimentacoes(carteiraId, M)
          .its('movimentacoes')
          .should((mov) => {
            expect(mov.entradas).to.have.length(1)
            expect(mov.entradas[0].pesoAtual).to.eq(30)
            expect(mov.saidas).to.have.length(1)
            expect(mov.saidas[0].pesoAnterior).to.eq(50)
            expect(mov.alteracoes).to.have.length(1)
            expect(mov.alteracoes[0]).to.include({
              pesoAnterior: 50,
              pesoAtual: 70,
              tipo: 'AUMENTOU',
            })
            expect(mov.mantidos).to.have.length(0)
            // Sem mistura: cada ativo aparece em um só grupo.
            const tickers = [
              ...mov.entradas.map((e) => e.ticker),
              ...mov.saidas.map((s) => s.ticker),
              ...mov.alteracoes.map((x) => x.ticker),
            ]
            expect(new Set(tickers).size).to.eq(tickers.length)
          })

        // Detalhe: o ativo que saiu não é composição vigente.
        detalhe(carteiraId)
          .its('versaoAtual.itens')
          .should((vigentes: Item[]) => {
            expect(vigentes.map((i) => i.ativoId)).not.to.include(b)
          })
      })

      // Carteira 2: mesma composição nos dois meses → só mantidos.
      novaCarteira().then((outraId) => {
        criarEPublicar(outraId, MENOS_1, itens([a, b], [50, 50]))
        criarEPublicar(outraId, M, itens([a, b], [50, 50]))
        movimentacoes(outraId, M)
          .its('movimentacoes')
          .should((mov) => {
            expect(mov.mantidos).to.have.length(2)
            expect(mov.entradas).to.have.length(0)
            expect(mov.saidas).to.have.length(0)
            expect(mov.alteracoes).to.have.length(0)
          })
      })
    })
  })

  // ATENÇÃO — deve FALHAR: `obterMovimentacoes` compara com a versão anterior NA LEITURA. Publicar
  // M-2 depois de M-1 faz as movimentações de M-1 mudarem (de "tudo entrou" para "A mantido").
  it('VER 08 · publicar uma competência antiga depois → as movimentações de uma competência já publicada não mudam (falha até congelar o snapshot)', () => {
    comoAdmin()

    cy.obterAtivosDeReferencia(2).then(([a, b]) => {
      novaCarteira().then((carteiraId) => {
        criarEPublicar(carteiraId, MENOS_1, itens([a, b], [50, 50]))
        movimentacoes(carteiraId, MENOS_1).as('antes')

        criarEPublicar(carteiraId, competenciaRelativa(-2), itens([a], [100]))

        cy.get('@antes').then((antes) => {
          movimentacoes(carteiraId, MENOS_1).should('deep.equal', antes)
        })
      })
    })
  })
})
